def normpath(path):
    if path == "":
        return "."
    if path.startswith("//") and not path.startswith("///"):
        leading = "//"
    elif path.startswith("/"):
        leading = "/"
    else:
        leading = ""
    parts = []
    for part in path.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if parts and parts[-1] != "..":
                parts.pop()
            elif not leading:
                parts.append("..")
        else:
            parts.append(part)
    result = leading + "/".join(parts)
    return result or "."

